import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const ThongTinCaNhan = () => {
    const navigate = useNavigate();
    const [profile, setProfile] = useState({ room_id: '', full_name: '', is_verified: false });
    const [isEditing, setIsEditing] = useState(false);

    useEffect(() => {
        // Lấy dữ liệu từ túi "user" (do Backend trả về lúc Login)
        const user = JSON.parse(localStorage.getItem('user') || '{}');
        if (user.room) {
            setProfile({
                room_id: user.room,
                full_name: user.ten,
                is_verified: true
            });
        }
    }, []);

    const handleUpdate = async () => {
        const user = JSON.parse(localStorage.getItem('user') || '{}');
        try {
            // 1. Lưu vào MySQL
            await axios.post('http://localhost:5000/api/tai-khoan/cap-nhat', {
                id: user.id,
                so_phong: profile.room_id,
                ho_ten: profile.full_name
            });

            // 2. Cập nhật localStorage để các trang khác (Bãi đỗ xe, Nhắn tin) dùng luôn
            const updatedUser = { ...user, room: profile.room_id, ten: profile.full_name };
            localStorage.setItem('user', JSON.stringify(updatedUser));

            setProfile({ ...profile, is_verified: true });
            setIsEditing(false);
            alert("Đã lưu thông tin vĩnh viễn!");
        } catch (err) {
            alert("Lỗi kết nối server!");
        }
    };

    return (
        <div style={containerStyle}>
            <div style={mainContentStyle}>
                {(!profile.is_verified || isEditing) ? (
                    <div>
                        <h3 style={{color: '#8b5e5e'}}>CẬP NHẬT THÔNG TIN CĂN HỘ</h3>
                        <select 
                            style={inputStyle}
                            value={profile.room_id}
                            onChange={(e) => setProfile({...profile, room_id: e.target.value})}
                        >
                            <option value="">-- Chọn phòng --</option>
                            <option value="101">101</option>
                            <option value="102">102</option>
                            {/* ... thêm các option khác */}
                        </select>
                        <input 
                            style={inputStyle}
                            placeholder="Họ tên"
                            value={profile.full_name}
                            onChange={(e) => setProfile({...profile, full_name: e.target.value})}
                        />
                        <button onClick={handleUpdate} style={btnSaveStyle}>XÁC NHẬN LƯU</button>
                    </div>
                ) : (
                    <div style={{textAlign: 'center'}}>
                        <h2>{profile.full_name}</h2>
                        <p>Phòng: <strong>{profile.room_id}</strong></p>
                        <button onClick={() => setIsEditing(true)} style={btnEditStyle}>SỬA THÔNG TIN</button>
                    </div>
                )}
            </div>
        </div>
    );
};

// --- STYLES (Rút gọn) ---
const containerStyle = { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', height: '100vh' };
const mainContentStyle = { backgroundColor: '#fff', padding: '40px', borderRadius: '20px', width: '400px', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' };
const inputStyle = { width: '100%', padding: '12px', marginBottom: '15px', borderRadius: '10px', border: '1px solid #ddd' };
const btnSaveStyle = { width: '100%', padding: '12px', backgroundColor: '#8b5e5e', color: '#fff', border: 'none', borderRadius: '10px', cursor: 'pointer' };
const btnEditStyle = { padding: '8px 20px', border: '1px solid #8b5e5e', background: 'none', color: '#8b5e5e', cursor: 'pointer' };

export default ThongTinCaNhan;
